  useEffect(() => {
    const interval = setInterval(() => {
      fetch('/api/dashboard/stats').then(r => r.json()).then(setData);
    }, 1000);
    return () => clearInterval(interval);
  }, []);
  return <div>{JSON.stringify(data)}</div>;
}
