app.get('/api/dashboard/stats', async (req, res) => {
  const revenue = await db.query('SELECT SUM(total) FROM orders');
  const users = await db.query('SELECT COUNT(*) FROM users');
  const products = await db.query('SELECT COUNT(*) FROM products WHERE stock = 0');
  res.json({ revenue: revenue.rows[0].sum, users: users.rows[0].count, outOfStock: products.rows[0].count });
});
